-- The ingredient tree, filled in for the shared ingredients the 2026-10-08
-- bar seeds added after the bottle catalog (20261008900100).
--
-- Those seeds brought 3,369 shared ingredients from public bar menus with no
-- role and no style: "1970s Cinzano Rosso" wasn't a kind of Sweet Vermouth,
-- "Aberfeldy 12 Whisky" wasn't a Scotch, "Al Pastor Cordial" wasn't a prep.
-- So spirit search, "can I make this", flavour rules and the same-spec check
-- for bar versions of a classic all missed them.
--
-- Every fold and every bottle here was checked against a real source (the
-- producer, a major retailer, Difford's Guide or Wikipedia), not memory:
--   * 609 copies fold into a bottle or style we already have, each one
--     confirmed as the same product and expression ("Cinzano 1757 Rosso",
--     "Cinzano 1757 Sweet Vermouth" and "1757 Vermouth di Torino Rosso" are
--     one bottle; Cinzano Rosso stays separate). 104 of them are bottles the
--     check found already in the catalog under another spelling. Folded names
--     stay as aliases, so typing one finds the bottle.
--   * 372 rows take their proper label name, brand first ("Cinzano
--     Bianco", "Caffè Borghetti", "Elijah Craig Small Batch"); the old name
--     stays an alias.
--   * 350 kept bottles get a corrected or more specific style.
--   * 2304 rows say what they are: 414 bottles, 1122 house preps,
--     768 styles; 2284 get their most specific style and 122 house
--     preps name the bottle they're made from.
--   * 5 new styles: Shrub, Sports Drink, Eggnog, Hop Water, Tepache.
--   * Bianco, blanc and blanco vermouth are one style (Bianco Vermouth).
--     Vermouth di Torino is an origin, not a style: Torino bottles file by
--     colour (rosso under Sweet Vermouth).
--
-- Left alone: bottles no source could confirm, names that could be several of
-- a brand's bottles ("Ardbeg", "Balvenie 12") and 431 names we couldn't place.
-- Matched by name key, so rows that don't exist here are skipped. Roles,
-- styles and made-from links are only filled where empty, except the checked
-- style corrections; a second run changes nothing. Venue ingredients aren't
-- touched: their names are private.

SET "app.image_worker" = 'on';

-- No paid flavour jobs (same rule as 20261008900100): note the queue now and
-- put it back at the end. New styles change some drinks' flavour rules; that
-- refill runs separately, once it's OK'd.
CREATE TEMP TABLE "flavor_jobs_before" AS SELECT * FROM "private"."item_flavor_jobs";

